const c = await api.peek("/customers", { status: "delayed" });
const m = await api.peek("/mails", { label: "complaint" });
return { customers: c, mails: m };

const cust = await api.get("/customers", {});
const mails = await api.get("/mails", { label: "complaint" });
const statuses = [...new Set((cust.items || []).map(c => c.order && c.order.status))];
const complaintIds = new Set((mails.items || []).map(m => m.customer_id));
return { total: cust.count, statuses, complaintCustomerIds: [...complaintIds], mailCount: mails.count };

const delayed = await api.get("/customers", { status: "delayed" });
const mails = await api.get("/mails", { label: "complaint" });
const delayedIds = (delayed.items || []).map(c => c.id);
const complaintIds = new Set((mails.items || []).map(m => m.customer_id));
const both = delayedIds.filter(id => complaintIds.has(id));
return { delayedIds, complaintIds: [...complaintIds], both };

